"""Google sign-in, the calls to Google (generated by Shikshya, P1b.6 R2): OpenID Connect, the authorization code flow
with PKCE. The only module that talks to Google or imports google-auth. The client id and secret come from the
environment (GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET) and the redirect address from PUBLIC_URL, never from the request."""
import base64
import hashlib
import secrets
from urllib.parse import urlencode

import requests
from django.conf import settings
from google.auth.transport.requests import Request as GoogleRequest
from google.oauth2 import id_token

AUTH_URL = "https://accounts.google.com/o/oauth2/v2/auth"
TOKEN_URL = "https://oauth2.googleapis.com/token"
CALLBACK_PATH = "/api/auth/google/callback/"
TIMEOUT_S = 10


class GoogleError(Exception):
    """Google refused the code or sent no id token."""


def configured() -> bool:
    return bool(settings.GOOGLE_CLIENT_ID and settings.GOOGLE_CLIENT_SECRET and settings.PUBLIC_URL)


def redirect_uri() -> str:
    return settings.PUBLIC_URL.rstrip("/") + CALLBACK_PATH


def new_pkce():
    """A PKCE verifier and its S256 challenge (RFC 7636)."""
    verifier = secrets.token_urlsafe(64)
    digest = hashlib.sha256(verifier.encode("ascii")).digest()
    return verifier, base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")


def auth_url(state: str, challenge: str) -> str:
    return AUTH_URL + "?" + urlencode({
        "client_id": settings.GOOGLE_CLIENT_ID, "redirect_uri": redirect_uri(), "response_type": "code",
        "scope": "openid email profile", "state": state, "code_challenge": challenge, "code_challenge_method": "S256",
        "access_type": "online", "prompt": "select_account"})


def verified_claims(code: str, verifier: str) -> dict:
    """Swap the code (with the client secret and the PKCE verifier) and verify the id token: Google's signature, the
    audience, the issuer and the expiry."""
    res = requests.post(TOKEN_URL, data={
        "code": code, "client_id": settings.GOOGLE_CLIENT_ID, "client_secret": settings.GOOGLE_CLIENT_SECRET,
        "redirect_uri": redirect_uri(), "grant_type": "authorization_code", "code_verifier": verifier},
        timeout=TIMEOUT_S)
    if res.status_code != 200:
        raise GoogleError("the token endpoint answered %s" % res.status_code)
    token = res.json().get("id_token")
    if not token:
        raise GoogleError("no id token")
    return id_token.verify_oauth2_token(token, GoogleRequest(), audience=settings.GOOGLE_CLIENT_ID,
                                        clock_skew_in_seconds=10)
